{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms, avg(duration)/1e6 avg_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, count(*), quantile_cont(duration,0.95)/1e6, avg(duration)/1e6 FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name='SELECT ts.orders_other' GROUP BY 1,2",
          "claim": "The ts-order-other-service 'SELECT ts.orders_other' DB span slowed from about 0.27 ms avg (p95 0.36 ms) to 139 ms avg (p95 416 ms)."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, count(*) n, sum(count) cnt, sum(sum)/nullif(sum(count),0) avg_ms FROM abnormal_metrics_histogram WHERE service_name='ts-order-other-service' AND metric IN ('db.client.connections.use_time','db.client.connections.wait_time') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, count(*), sum(count), sum(sum)/nullif(sum(count),0) FROM normal_metrics_histogram WHERE service_name='ts-order-other-service' AND metric IN ('db.client.connections.use_time','db.client.connections.wait_time') GROUP BY 1,2",
          "claim": "DB connection use time rose from about 0.6 ms to 236 ms, and wait time from 0.06 ms to 28 ms, on ts-order-other-service."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, avg(value) avg_v, max(value) max_v FROM abnormal_metrics WHERE service_name='mysql' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') GROUP BY 1,2",
          "claim": "mysql CPU (about 0.02 cores) and memory stayed flat, so the slowdown is not explained by database saturation."
        },
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT parent_span_id pid, sum(duration) cd FROM abnormal_traces GROUP BY 1) SELECT s.span_name, count(*) n, quantile_cont(s.duration - coalesce(c.cd,0),0.5)/1e6 own_p50_ms, quantile_cont(s.duration - coalesce(c.cd,0),0.95)/1e6 own_p95_ms FROM abnormal_traces s LEFT JOIN c ON c.pid=s.span_id WHERE s.service_name='ts-order-other-service' AND s.span_name='OrderOtherRepository.findAll' GROUP BY 1",
          "claim": "OrderOtherRepository.findAll self-time grew from about 0.9 ms to a median of 416 ms, with the same pattern in its DB calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, quantile_cont(c.duration,0.95)/1e6 callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND c.attr_span_kind='Server' AND p.service_name='ts-admin-order-service' GROUP BY 1,2,3",
          "claim": "ts-admin-order-service calls to ts-order-other-service's orderOther endpoints show p95 of about 25 s in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, quantile_cont(c.duration,0.95)/1e6 callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-admin-order-service' AND c.attr_span_kind='Server' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2,3",
          "claim": "ts-ui-dashboard calls to ts-admin-order-service adminorder endpoints show p95 of about 1.4 s, versus about 15 ms normally."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, quantile_cont(c.duration,0.95)/1e6 callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-order-other-service' AND c.attr_span_kind='Server' AND p.service_name='ts-ui-dashboard' GROUP BY 1,2,3",
          "claim": "ts-ui-dashboard's calls to ts-order-other-service refresh endpoint show p95 of about 422 ms, versus about 4 ms normally."
        }
      ]
    }
  ]
}
